  AUTOMATIONS_READ: 'automations:read',
  AUTOMATIONS_WRITE: 'automations:write',
  ENROLLMENTS_READ: 'enrollments:read',
  TEMPLATES_READ: 'templates:read',
  TEMPLATES_WRITE: 'templates:write',
  WEBHOOKS_READ: 'webhooks:read',
